-- Une écriture concurrente (un prof qui édite un modèle) fait échouer proprement la migration
-- au lieu d'empiler les écritures en attente.
set local lock_timeout = '5s';

-- ---- 1. Les opérations, en tables temporaires ---------------------------------------------
