  ($nf$Suites > Généralités sur les suites > deviner le terme général$nf$, $nf$subnotion$nf$),
  ($nf$Suites > Suites arithmétiques > calculer un terme$nf$, $nf$subnotion$nf$),
  ($nf$Suites > Suites arithmétiques > raison$nf$, $nf$subnotion$nf$),
  ($nf$Suites > Suites arithmétiques > reconnaître$nf$, $nf$subnotion$nf$),
  ($nf$Suites > Suites et modélisation > algorithmes$nf$, $nf$subnotion$nf$),
  ($nf$Suites > Suites et modélisation > placements$nf$, $nf$subnotion$nf$),
  ($nf$Suites > Suites et modélisation > pourcentages$nf$, $nf$subnotion$nf$),
  ($nf$Suites > Suites géométriques > calculer un terme$nf$, $nf$subnotion$nf$),
  ($nf$Suites > Suites géométriques > raison$nf$, $nf$subnotion$nf$),
  ($nf$Suites > Suites géométriques > reconnaître$nf$, $nf$subnotion$nf$),
  ($nf$Équations différentielles > y′ = ay + b > condition initiale$nf$, $nf$subnotion$nf$),
  ($nf$Équations différentielles > y′ = ay + b > solution générale$nf$, $nf$subnotion$nf$),
  ($nf$Équations différentielles > y′ = ay + f > solution générale$nf$, $nf$subnotion$nf$),
  ($nf$Équations différentielles > y′ = ay + f > solution particulière donnée$nf$, $nf$subnotion$nf$),
  ($nf$Équations différentielles > y′ = ay > condition initiale$nf$, $nf$subnotion$nf$),
  ($nf$Équations différentielles > y′ = ay > solution générale$nf$, $nf$subnotion$nf$),
  ($nf$Équations différentielles > y′ = f > formes u′eᵘ, 2uu′, u′/u$nf$, $nf$subnotion$nf$),
  ($nf$Équations différentielles > y′ = f > sinus et cosinus$nf$, $nf$subnotion$nf$),
  ($nf$Géométrie > Espace : avec coordonnées$nf$, $nf$notion$nf$),
  ($nf$Géométrie > Orthogonalité : avec coordonnées$nf$, $nf$notion$nf$),
  ($nf$Géométrie > Vecteurs : avec coordonnées$nf$, $nf$notion$nf$);

-- ---- 2. Résolution STRICTE des chemins d'aujourd'hui, AVANT tout changement ---------------
create temporary table _nf_id as
	select r.ref, case when r.notion is null then b.id when r.sous_notion is null then nn.id else s.id end as id
	  from _nf_ref r
	  left join public.classification_nodes b on b.kind = 'branch' and b.parent_id is null and b.name = r.branche
	  left join public.classification_nodes nn on r.notion is not null and nn.kind = 'notion' and nn.parent_id = b.id and nn.name = r.notion
	  left join public.classification_nodes s on r.sous_notion is not null and s.kind = 'subnotion' and s.parent_id = nn.id and s.name = r.sous_notion;
do $resolution$
begin
	if exists (select 1 from _nf_id where id is null) then
		raise exception 'chemins introuvables dans l''arbre : %', (select string_agg(ref, ' | ') from _nf_id where id is null);
	end if;
end $resolution$;

-- ---- 3. Gardes : l'arbre est dans l'état attendu, sinon RIEN ne change ---------------------
do $garde$
declare
	v_n integer; v_presents integer; v_bien integer;
begin
	-- 3a. tous les nœuds en jeu sont actifs
	select count(*) into v_n from _nf_id i join public.classification_nodes n on n.id = i.id where n.archived_at is not null;
	if v_n <> 0 then
		raise exception 'état inattendu : % nœud(s) en jeu déjà archivé(s)', v_n;
	end if;
	-- 3b. les sous-notions à créer n'existent pas encore
	select count(*) into v_n from _nf_creer c join _nf_id p on p.ref = c.parent_ref
	  join public.classification_nodes n on n.parent_id = p.id and lower(n.name) = lower(c.nom);
	if v_n <> 0 then
		raise exception 'état inattendu : % sous-notion(s) à créer existe(nt) déjà', v_n;
	end if;
	-- 3c. les nœuds à renommer portent encore leur ancien nom
	select count(*) into v_n from _nf_renommer r join _nf_id i on i.ref = r.ref
	  join public.classification_nodes n on n.id = i.id where n.name <> r.ancien_nom;
	if v_n <> 0 then
		raise exception 'état inattendu : % nœud(s) déjà renommé(s)', v_n;
	end if;
	-- 3d. chaque point (nouvelle génération : grade non nul) existe une fois, sur son nœud de départ
	select count(*), count(*) filter (where p.node_id = d.id) into v_presents, v_bien
	  from _nf_points x join public.curriculum_points p on p.code = x.code and p.grade is not null
	  join _nf_id d on d.ref = x.de_ref;
	if v_presents <> 125 or v_bien <> 125 then
		raise exception 'état inattendu : points présents %/125, sur leur nœud de départ %/125', v_presents, v_bien;
	end if;
	-- 3e. modèles : TOUT ou RIEN, et sur leur nœud de départ
	select count(*), count(*) filter (where q.classification_node_id = d.id) into v_presents, v_bien
	  from _nf_modeles m join public.question_templates q on q.id = m.id join _nf_id d on d.ref = m.de_ref;
	if v_presents not in (0, 234) then
		raise exception 'identifiants partiellement présents : % modèle(s) sur 234', v_presents;
	end if;
	if v_bien <> v_presents then
		raise exception 'état inattendu : % modèle(s) hors de leur nœud de départ', v_presents - v_bien;
	end if;
	-- 3f. rangements d'exercices : TOUT ou RIEN (les 49 à déplacer et les 4 doublons), doublons présents
	select (select count(*) from _nf_rangements r join _nf_id d on d.ref = r.de_ref
	          join public.exercise_classifications c on c.exercise_id = r.exercise_id and c.node_id = d.id
	           and c.is_primary = r.principal)
	     + (select count(*) from _nf_suppressions s join _nf_id d on d.ref = s.de_ref join _nf_id g on g.ref = s.garde_ref
	          join public.exercise_classifications c on c.exercise_id = s.exercise_id and c.node_id = d.id
	           and c.is_primary = s.principal_transfere
	          join public.exercise_classifications k on k.exercise_id = s.exercise_id and k.node_id = g.id
	           and (not s.principal_transfere or not k.is_primary))
	  into v_presents;
	if v_presents not in (0, 53) then
		raise exception 'identifiants partiellement présents : % rangement(s) d''exercice sur 53', v_presents;
	end if;
end $garde$;

-- ---- 4. Créer les sous-notions (à la suite des enfants du parent) -------------------------
create temporary table _nf_crees (chemin_final text primary key, id uuid not null);
with ins as (
	insert into public.classification_nodes (kind, parent_id, name, position)
	select 'subnotion', p.id, c.nom,
	       (select coalesce(max(x.position), -1) + 1 from public.classification_nodes x where x.parent_id = p.id)
	  from _nf_creer c join _nf_id p on p.ref = c.parent_ref
	returning id, parent_id, name
)
insert into _nf_crees (chemin_final, id)
select c.chemin_final, ins.id from ins join _nf_creer c on c.nom = ins.name join _nf_id p on p.ref = c.parent_ref and p.id = ins.parent_id;

-- Destination de chaque objet : un nœud d'aujourd'hui ou une sous-notion créée
create temporary table _nf_dest as
	select x.vers_ref as cle, i.id from (select vers_ref from _nf_points union select vers_ref from _nf_modeles
	       union select vers_ref from _nf_rangements) x join _nf_id i on i.ref = x.vers_ref where x.vers_ref is not null
	union
	select '+' || c.chemin_final, c.id from _nf_crees c;

-- ---- 5. Re-parenter (à la suite des enfants du nouveau parent, dans l'ordre) ---------------
update public.classification_nodes n set parent_id = r.parent_id, position = r.position
  from (select i.id, p.id as parent_id,
               (select coalesce(max(x.position), -1) from public.classification_nodes x where x.parent_id = p.id)
               + row_number() over (partition by p.id order by o.ordre) as position
          from _nf_reparenter o join _nf_id i on i.ref = o.ref join _nf_id p on p.ref = o.parent_ref) r
 where n.id = r.id;

-- ---- 6. Renommer --------------------------------------------------------------------------
update public.classification_nodes n set name = r.nouveau_nom
  from _nf_renommer r join _nf_id i on i.ref = r.ref where n.id = i.id;

-- ---- 7. Re-rattacher les points -----------------------------------------------------------
update public.curriculum_points p set node_id = d.id
  from _nf_points x join _nf_dest d on d.cle = coalesce(x.vers_ref, '+' || x.vers_cree)
 where p.code = x.code and p.grade is not null;

-- ---- 8. Ranger les modèles ailleurs, `updated_at` préservé ----------------------------------
alter table public.question_templates disable trigger update_question_templates_updated_at;
update public.question_templates q set classification_node_id = d.id
  from _nf_modeles m join _nf_dest d on d.cle = coalesce(m.vers_ref, '+' || m.vers_cree)
 where q.id = m.id;
alter table public.question_templates enable trigger update_question_templates_updated_at;

-- ---- 9. Rangements d'exercices : doublons supprimés (principal transféré), puis déplacés ---
delete from public.exercise_classifications c
 using _nf_suppressions s join _nf_id d on d.ref = s.de_ref
 where c.exercise_id = s.exercise_id and c.node_id = d.id;
update public.exercise_classifications c set is_primary = true
  from _nf_suppressions s join _nf_id g on g.ref = s.garde_ref
 where s.principal_transfere and c.exercise_id = s.exercise_id and c.node_id = g.id;
update public.exercise_classifications c set node_id = v.id
  from _nf_rangements r join _nf_id d on d.ref = r.de_ref join _nf_dest v on v.cle = coalesce(r.vers_ref, '+' || r.vers_cree)
 where c.exercise_id = r.exercise_id and c.node_id = d.id;

-- ---- 10. Archiver : les sous-notions, puis les notions --------------------------------------
update public.classification_nodes n set archived_at = now()
  from _nf_archiver a join _nf_id i on i.ref = a.ref where n.id = i.id and a.kind = 'subnotion';
update public.classification_nodes n set archived_at = now()
  from _nf_archiver a join _nf_id i on i.ref = a.ref where n.id = i.id and a.kind = 'notion';

-- ---- 11. Vérifications ----------------------------------------------------------------------
do $check$
declare
	v_n integer; v_m integer;
begin
	select count(*) into v_n from _nf_crees c join public.classification_nodes n on n.id = c.id where n.archived_at is null;
	if v_n <> 3 then raise exception 'sous-notions créées : %/3', v_n; end if;
	select count(*) into v_n from _nf_reparenter o join _nf_id i on i.ref = o.ref join _nf_id p on p.ref = o.parent_ref
	  join public.classification_nodes n on n.id = i.id and n.parent_id = p.id;
	if v_n <> 6 then raise exception 'nœuds re-parentés : %/6', v_n; end if;
	select count(*) into v_n from _nf_renommer r join _nf_id i on i.ref = r.ref
	  join public.classification_nodes n on n.id = i.id and n.name = r.nouveau_nom;
	if v_n <> 63 then raise exception 'nœuds renommés : %/63', v_n; end if;
	select count(*) into v_n from _nf_archiver a join _nf_id i on i.ref = a.ref
	  join public.classification_nodes n on n.id = i.id and n.archived_at is not null;
	if v_n <> 74 then raise exception 'nœuds archivés : %/74', v_n; end if;
	select count(*) into v_n from _nf_points x join _nf_dest d on d.cle = coalesce(x.vers_ref, '+' || x.vers_cree)
	  join public.curriculum_points p on p.code = x.code and p.grade is not null and p.node_id = d.id;
	if v_n <> 125 then raise exception 'points re-rattachés : %/125', v_n; end if;
	select count(*) into v_m from _nf_modeles m join public.question_templates q on q.id = m.id;
	select count(*) into v_n from _nf_modeles m join _nf_dest d on d.cle = coalesce(m.vers_ref, '+' || m.vers_cree)
	  join public.question_templates q on q.id = m.id and q.classification_node_id = d.id;
	if v_n <> v_m or v_m not in (0, 234) then raise exception 'modèles rangés : %/%', v_n, v_m; end if;
	-- Plus rien sur un nœud archivé : ni point, ni modèle, ni rangement d'exercice
	select (select count(*) from public.curriculum_points p join public.classification_nodes n on n.id = p.node_id
	         where n.archived_at is not null)
	     + (select count(*) from public.question_templates q join public.classification_nodes n on n.id = q.classification_node_id
	         where n.archived_at is not null)
	     + (select count(*) from public.exercise_classifications c join public.classification_nodes n on n.id = c.node_id
	         where n.archived_at is not null)
	  into v_n;
	if v_n <> 0 then raise exception 'contenus restés sur un nœud archivé : %', v_n; end if;
	-- Chaque exercice touché garde exactement un rangement principal
	select count(*) into v_n from (select c.exercise_id from public.exercise_classifications c
	         where c.exercise_id in (select exercise_id from _nf_rangements union select exercise_id from _nf_suppressions)
	         group by c.exercise_id having count(*) filter (where c.is_primary) <> 1) x;
	if v_n <> 0 then raise exception 'exercices sans rangement principal unique : %', v_n; end if;
end $check$;

drop table _nf_dest; drop table _nf_crees; drop table _nf_id; drop table _nf_ref; drop table _nf_creer;
drop table _nf_reparenter; drop table _nf_renommer; drop table _nf_points; drop table _nf_modeles;
drop table _nf_rangements; drop table _nf_suppressions; drop table _nf_archiver;
